#[inline]
pub(super) fn create_vertex_shader(
    device: &ID3D11Device,
    bytes: &[u8],
) -> Result<ID3D11VertexShader> {
    unsafe {
        let mut shader = None;
        device.CreateVertexShader(bytes, None, Some(&mut shader))?;
        Ok(shader.unwrap())
    }
}

